from datetime import datetime

def parse_dt(s):
    if s is None:
        return None
    if isinstance(s, dt.datetime):
        return s
    t=str(s)
    t=t.replace('Z','+00:00')
    try:
        return datetime.fromisoformat(t)
    except Exception:
        # date only
        try:
            return datetime.strptime(t.split('T')[0], '%Y-%m-%d')
        except Exception:
            return None

